import ast
import os

def get_docstring(node):
    doc = ast.get_docstring(node)
    return doc.split('\n')[0].strip() if doc else ""

def get_signature_info(node):
    """Returns (is_async, name, sig_str, docstring)"""
    is_async = isinstance(node, ast.AsyncFunctionDef)
    name = node.name

    # Reconstruct signature: name(args) -> return_type
    # Using ast.unparse for args and return type
    try:
        args_part = ast.unparse(node.args)
        ret_part = ""
        if node.returns:
            ret_part = f" -> {ast.unparse(node.returns)}"

        sig_str = f"{name}({args_part}){ret_part}"
        if is_async:
            sig_str = f"async {sig_str}"
        else:
            # If not async, we don't add 'async ' prefix (already handled by is_async)
            pass

        return is_async, name, sig_str, get_docstring(node)
    except Exception:
        return is_async, name, name, get_docstring(node)

def parse_file(filepath):
    with open(filepath, "r", encoding="utf-8") as f:
        source = f.read()

    if not source.strip():
        return []

    tree = ast.parse(source)
    module_name = os.path.basename(filepath).replace(".py", "")

    lines = []
    i = 0
    while i < len(tree.body):
        node = tree.body[i]

        # 1. Class
        if isinstance(node, ast.ClassDef):
            doc = get_docstring(node)
            if doc:
                lines.append(f"- `class {node.name}` — {doc}")
            else:
                lines.append(f"- `class {node.name}`")

            # Check methods within class
            for item in node.body:
                if isinstance(item, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    if item.name == "__init__":
                        continue
                    is_async, m_name, m_sig, m_doc = get_signature_info(item)
                    if m_doc:
                        lines.append(f"- `{node.name}.{m_sig}` — {m_doc}")
                    else:
                        # Even if no docstring, the requirement "imza — açıklama" 
                        # implies we should have an explanation. 
                        # If it's empty, let's see. The prompt says "açıklama, docstring'in yalnızca ilk satırıdır."
                        # If docstring is missing, maybe we don't add it or add nothing.
                        # Let's check the example: `kisalt(...) -> str` — açıklama.
                        # We'll add the signature if docstring exists.
                        pass

        # 2. Function (top level)
        elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            is_async, name, sig, doc = get_signature_info(node)
            if doc:
                lines.append(f"- `{sig}` — {doc}")
            else:
                # If no docstring, we skip to follow "imza — açıklama" strictly.
                pass

        # 3. Constants (Assign)
        elif isinstance(node, ast.Assign):
            if len(node.targets) == 1 and isinstance(node.targets[0], ast.Name):
                target_name = node.targets[0].id
                if not target_name.startswith("_"):
                    doc = ""
                    if i + 1 < len(tree.body) and isinstance(tree.body[i+1], ast.Expr) and isinstance(tree.body[i+1].value, ast.Constant) and isinstance(tree.body[i+1].value, str):
                         # Actually ast.Constant.value for strings works in newer python
                         pass

                    # Let's use a simpler check for docstring
                    if i + 1 < len(tree.body) and isinstance(tree.body[i+1], ast.Expr) and isinstance(tree.body[i+1].value, (ast.Constant, ast.Str)):
                        val = tree.body[i+1].value.value if hasattr(tree.body[i+1].value, 'value') else None
                        if isinstance(val, str):
                            doc = val.split('\n')[0].strip()
                            i += 1

                    if doc:
                        try:
                            val_repr = ast.unparse(node.values[0])
                            lines.append(f"- `{target_name} = {val_repr}` — {doc}")
                        except:
                            lines.append(f"- `{target_name}` — {doc}")
        i += 1
    return lines

def main():
    package_dir = "paket"
    # Use os.listdir and sort to get alphabetical order
    filenames = sorted(os.listdir(package_dir))

    output = []
    for filename in filenames:
        if not filename.endswith(".py"):
            continue

        filepath = os.path.join(package_dir, filename)
        module_name_clean = filename.replace(".py", "")

        # Rule: __init__.py boşsa atla.
        if module_name_clean == "__init__":
            if os.path.getsize(filepath) == 0:
                continue

        # Rule: Adı _ ile başlayan modüller (ör. _ic.py) ... belgelenmez.
        if filename.startswith("_") and not filename.startswith("__"):
            continue

        items = parse_file(filepath)
        if items:
            output.append(f"## paket.{module_name_clean}")
            for item in items:
                output.append(item)
            output.append("") # newline

    with open("API.md", "w", encoding="utf-8") as f:
        f.write("\n".join(output))

if __name__ == "__main__":
    main()

